ee:message.ee:set-payload:
%dw 2.0
output application/json
---
payload map (ticket) -> do {
    var policyMatches =
        vars.slaPolicy.slaPolicies filter ((p) ->
            p.priority == ticket.priority
            and p.customerTier == ticket.customer_tier
        )

    var policy =
        policyMatches[0]

    var calendar =
        vars.slaPolicy.businessCalendars[policy.calendar]

    var thresholds =
        vars.slaPolicy.thresholds

    var currentTime =
        (now() >> calendar.timeZone) as LocalDateTime

    // Database TIMESTAMP values are interpreted as UTC,
    // then converted into the SLA calendar's local time.
    fun toCalendarLocalDateTime(value, timeZone) =
        if (value == null)
            null
        else
            (((value as LocalDateTime) ++ |Z|) >> timeZone)
                as LocalDateTime

    var createdDateTime =
        if (ticket.created_at != null)
            toCalendarLocalDateTime(
                ticket.created_at,
                calendar.timeZone
            )
        else
            currentTime

    var responseReceived =
        ticket.first_response_at != null

    var responseEnd =
        if (responseReceived)
            toCalendarLocalDateTime(
                ticket.first_response_at,
                calendar.timeZone
            )
        else
            currentTime

    var resolutionComplete =
        ticket.resolved_at != null

    var resolutionEnd =
        if (resolutionComplete)
            toCalendarLocalDateTime(
                ticket.resolved_at,
                calendar.timeZone
            )
        else
            currentTime

    var responseTarget =
        (policy.firstResponseTargetMins default 0) as Number

    var resolutionTarget =
        (policy.resolutionTargetMins default 0) as Number

    var pauseIntervals =
        read(
            (ticket.pause_intervals_json default "[]"),
            "application/json"
        )

    fun businessMinutes(startLdt, endLdt, cal) =
        if (endLdt <= startLdt)
            0
        else do {
            var startDate = startLdt as Date
            var endDate = endLdt as Date
            var dayCount = daysBetween(startDate, endDate)

            var dates =
                (0 to dayCount) map ((offset) ->
                    startDate +
                    (("P" ++ (offset as String) ++ "D") as Period)
                )

            ---
            sum(dates map ((dayDate) -> do {
                var dayName =
                    ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"]
                        [dayDate.dayOfWeek - 1]

                var dateText =
                    dayDate as String {format: "yyyy-MM-dd"}

                var openTime =
                    cal.workingHours.start as LocalTime {format: "HH:mm"}

                var closeTime =
                    cal.workingHours.end as LocalTime {format: "HH:mm"}

                var dayOpen =
                    dayDate ++ openTime

                var dayClose =
                    if (
                        cal.workingHours.start == "00:00"
                        and cal.workingHours.end == "23:59"
                    )
                        (dayDate + |P1D|) ++
                            ("00:00" as LocalTime {format: "HH:mm"})
                    else
                        dayDate ++ closeTime

                var clippedStart =
                    if (startLdt > dayOpen)
                        startLdt
                    else
                        dayOpen

                var clippedEnd =
                    if (endLdt < dayClose)
                        endLdt
                    else
                        dayClose

                var isWorkingDay =
                    cal.workingDays contains dayName

                var isHoliday =
                    (cal.holidays default []) contains dateText

                ---
                if (
                    isWorkingDay
                    and not isHoliday
                    and clippedEnd > clippedStart
                )
                    (
                        (clippedEnd - clippedStart)
                            as Number {unit: "milliseconds"}
                    ) / 60000
                else
                    0
            }))
        }

    fun pausedBusinessMinutes(startLdt, endLdt, intervals, cal) =
        if (endLdt <= startLdt or isEmpty(intervals))
            0
        else
            sum(intervals map ((pause) -> do {
                var pauseStart =
                    toCalendarLocalDateTime(
                        pause.paused_from,
                        cal.timeZone
                    )

                var pauseEnd =
                    if (pause.paused_to != null)
                        toCalendarLocalDateTime(
                            pause.paused_to,
                            cal.timeZone
                        )
                    else
                        endLdt

                var clippedStart =
                    if (pauseStart > startLdt)
                        pauseStart
                    else
                        startLdt

                var clippedEnd =
                    if (pauseEnd < endLdt)
                        pauseEnd
                    else
                        endLdt

                ---
                businessMinutes(
                    clippedStart,
                    clippedEnd,
                    cal
                )
            }))

    var responseBusinessMinutes =
        businessMinutes(
            createdDateTime,
            responseEnd,
            calendar
        )

    var resolutionBusinessMinutes =
        businessMinutes(
            createdDateTime,
            resolutionEnd,
            calendar
        )

    var responsePausedMinutes =
        pausedBusinessMinutes(
            createdDateTime,
            responseEnd,
            pauseIntervals,
            calendar
        )

    var resolutionPausedMinutes =
        pausedBusinessMinutes(
            createdDateTime,
            resolutionEnd,
            pauseIntervals,
            calendar
        )

    var responseElapsed =
        max([0, responseBusinessMinutes - responsePausedMinutes])

    var resolutionElapsed =
        max([0, resolutionBusinessMinutes - resolutionPausedMinutes])

    var responsePercent =
        if (responseTarget > 0)
            responseElapsed / responseTarget * 100
        else
            0

    var resolutionPercent =
        if (resolutionTarget > 0)
            resolutionElapsed / resolutionTarget * 100
        else
            0

    fun band(percent) =
        if (
            percent >=
            (
                (thresholds.breachPercent as Number)
                * (thresholds.severeMultiplier as Number)
            )
        )
            "SEVERELY_BREACHED"
        else if (percent >= (thresholds.breachPercent as Number))
            "BREACHED"
        else if (percent >= (thresholds.atRiskPercent as Number))
            "AT_RISK"
        else
            "ON_TRACK"

    fun alertLevel(slaBand: String): Number =
        if (slaBand == "SEVERELY_BREACHED")
            3
        else if (slaBand == "BREACHED")
            2
        else if (slaBand == "AT_RISK")
            1
        else
            0

    ---
    {
        ticket_id: ticket.ticket_id,
        subject: ticket.subject,
        priority: ticket.priority,
        ticket_status: ticket.ticket_status,

        created_at: ticket.created_at,
        first_response_at: ticket.first_response_at,
        resolved_at: ticket.resolved_at,

        customer_id: ticket.customer_id,
        customer_tier: ticket.customer_tier,
        assigned_agent_id: ticket.assigned_agent_id,
        manager_id: ticket.manager_id,
        manager_email: ticket.manager_email,
        manager_status: ticket.manager_status,

        business_calendar_code: policy.calendar,

        first_response_target_mins: responseTarget,
        resolution_target_mins: resolutionTarget,

        response_received: responseReceived,
        resolution_complete: resolutionComplete,

        response_elapsed_mins: responseElapsed,
        resolution_elapsed_mins: resolutionElapsed,

        response_percent: responsePercent,
        resolution_percent: resolutionPercent,

        response_band: band(responsePercent),
        resolution_band: band(resolutionPercent),

        current_alert_level_response:
            alertLevel(band(responsePercent)),

        current_alert_level_resolution:
            alertLevel(band(resolutionPercent)),

        last_alert_level_response:
            ticket.last_alert_level_response default 0,

        last_alert_level_resolution:
            ticket.last_alert_level_resolution default 0,

        paused_minutes: resolutionPausedMinutes
    }
}

db:update.db:sql:
UPDATE public.sla_evaluation_runs
SET events_published = COALESCE(events_published, 0) + 1
WHERE run_id = :runId;

set-payload.value:
#[{
    run_id: vars.recoveryRun.run_id,
    alert_seq: vars.recoveryRun.alert_seq,
    isRecovery: true
}]

db:update.db:input-parameters:
#[{
    alertSeq: vars.currentAlert.alert_seq,
    runId: vars.currentAlert.run_id,
    claimToken: "RUN-" ++ (vars.currentAlert.run_id as String)
}]

db:select.db:input-parameters:
#[{
    alertSeq: vars.currentAlert.alert_seq,
    runId: vars.currentAlert.run_id,
    claimToken: "RUN-" ++ (vars.currentAlert.run_id as String)
}]

db:update.db:sql:
UPDATE public.sla_evaluation_runs
SET suppressed_count = COALESCE(suppressed_count, 0) + 1
WHERE run_id = :runId;

UPDATE public.sla_evaluation_runs
SET digests_sent = COALESCE(digests_sent, 0) + 1	
WHERE run_id = :runId;
